 10	
 11	// Source identifies the probe path that produced a utilization sample.
 12	type Source string
 13	
 14	const (
 15		SourceUnknown      Source = "unknown"
 16		SourceVLLMMetrics  Source = "vllm.metrics"
 17		SourceLlamaMetrics Source = "llama-server.metrics"
 18		SourceLlamaSlots   Source = "llama-server.slots"
 19	)
 20	
 21	// Freshness describes whether a sample was observed just now, reused after a
 22	// failed probe, or has no known prior observation.
 23	type Freshness string
 24	
 25	const (
 26		FreshnessFresh   Freshness = "fresh"
 27		FreshnessStale   Freshness = "stale"
 28		FreshnessUnknown Freshness = "unknown"
 29	)
 30	
 31	// EndpointUtilization is the normalized utilization shape shared by local
 32	// provider probes.
 33	type EndpointUtilization struct {
 34		ActiveRequests *int
 35		QueuedRequests *int
 36		CacheUsage     *float64
 37		MaxConcurrency *int
 38		Source         Source
 39		Freshness      Freshness
 40		ObservedAt     time.Time
 41	}
 42	
 43	// Cache preserves the most recent successful sample so probe failures can
 44	// return stale utilization instead of surfacing hard endpoint unavailability.
 45	type Cache struct {
 46		mu   sync.Mutex
 47		last *EndpointUtilization
 48	}
 49	
 50	// Remember stores a fresh sample and returns a normalized copy with fresh
 51	// freshness and an observed timestamp.
 52	func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
 53		c.mu.Lock()
 54		defer c.mu.Unlock()
 55	
 56		now := time.Now().UTC()
 57		sample.Freshness = FreshnessFresh
 58		sample.ObservedAt = now
 59		stored := clone(sample)
 60		c.last = &stored
 61		return stored
 62	}
 63	
 64	// Stale returns the last successful sample marked stale. The boolean reports
 65	// whether a previous sample existed.
 66	func (c *Cache) Stale() (EndpointUtilization, bool) {
 67		c.mu.Lock()
 68		defer c.mu.Unlock()
 69	
 70		if c.last == nil {
 71			return EndpointUtilization{}, false
 72		}
 73		stale := clone(*c.last)
 74		stale.Freshness = FreshnessStale
 75		return stale, true
 76	}
 77	
 78	// Unknown returns a sample with unknown freshness and no numeric values.
 79	func Unknown(source Source) EndpointUtilization {
 80		return EndpointUtilization{
 81			Source:    source,
 82			Freshness: FreshnessUnknown,
 83		}
 84	}
 85	
 86	// Int returns a pointer to v.
 87	func Int(v int) *int {
 88		return &v
 89	}
 90	
 91	// Float64 returns a pointer to v.
 92	func Float64(v float64) *float64 {
 93		return &v
 94	}
 95	
 96	// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
 97	// base URL while preserving the scheme, host, and any prefix path.
 98	func ServerRoot(baseURL string) string {
 99		trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
100		if trimmed == "" {
101			return ""
102		}
103	
104		parsed, err := url.Parse(trimmed)
105		if err != nil {
106			return strings.TrimSuffix(trimmed, "/v1")
107		}
108	
109		parsed.Fragment = ""
110		parsed.RawQuery = ""
111		path := strings.TrimRight(parsed.Path, "/")
112		if strings.HasSuffix(path, "/v1") {
113			path = strings.TrimSuffix(path, "/v1")
114		}
115		parsed.Path = path
116		return strings.TrimRight(parsed.String(), "/")
117	}
118	
119	// ParsePrometheusMetricValue returns the first numeric value for metric from
120	// a Prometheus-style plaintext metrics body.
121	func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
122		for _, line := range strings.Split(body, "\n") {
123			line = strings.TrimSpace(line)
124			if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
125				continue
126			}
127			rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
128			if strings.HasPrefix(rest, "{") {
129				if idx := strings.Index(rest, "}"); idx >= 0 {
130					rest = strings.TrimSpace(rest[idx+1:])
131				}
132			}
133			fields := strings.Fields(rest)
134			if len(fields) == 0 {
135				continue
136			}
137			val, err := strconv.ParseFloat(fields[0], 64)
138			if err == nil {
139				return val, true
140			}
141		}
142		return 0, false
143	}
144	
145	func clone(sample EndpointUtilization) EndpointUtilization {
146		out := sample
147		if sample.ActiveRequests != nil {
148			out.ActiveRequests = Int(*sample.ActiveRequests)
149		}
150		if sample.QueuedRequests != nil {
151			out.QueuedRequests = Int(*sample.QueuedRequests)
152		}
153		if sample.CacheUsage != nil {
154			out.CacheUsage = Float64(*sample.CacheUsage)
155		}
156		if sample.MaxConcurrency != nil {
157			out.MaxConcurrency = Int(*sample.MaxConcurrency)
158		}
159		return out
160	}

