     8		"strings"
     9	
    10		"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
    11	)
    12	
    13	// UtilizationProbe queries vLLM server-root observability endpoints and
    14	// normalizes them into the shared endpoint utilization shape.
    15	type UtilizationProbe struct {
    16		baseURL string
    17		client  *http.Client
    18		cache   utilization.Cache
    19	}
    20	
    21	// NewUtilizationProbe creates a probe for an OpenAI-compatible vLLM base URL.
    22	func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
    23		if client == nil {
    24			client = http.DefaultClient
    25		}
    26		return &UtilizationProbe{
    27			baseURL: baseURL,
    28			client:  client,
    29		}
    30	}
    31	
    32	// Probe fetches /metrics from the server root and returns a normalized sample.
    33	// Failures return stale or unknown utilization instead of surfacing endpoint
    34	// unavailability.
    35	func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
    36		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
    37		if err != nil {
    38			if stale, ok := p.cache.Stale(); ok {
    39				return stale
    40			}
    41			return utilization.Unknown(utilization.SourceVLLMMetrics)
    42		}
    43	
    44		running, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_running")
    45		if !ok {
    46			if stale, ok := p.cache.Stale(); ok {
    47				return stale
    48			}
    49			return utilization.Unknown(utilization.SourceVLLMMetrics)
    50		}
    51		waiting, ok := utilization.ParsePrometheusMetricValue(body, "vllm:num_requests_waiting")
    52		if !ok {
    53			if stale, ok := p.cache.Stale(); ok {
    54				return stale
    55			}
    56			return utilization.Unknown(utilization.SourceVLLMMetrics)
    57		}
    58	
    59		sample := utilization.EndpointUtilization{
    60			ActiveRequests: utilization.Int(int(running)),
    61			QueuedRequests: utilization.Int(int(waiting)),
    62			Source:         utilization.SourceVLLMMetrics,
    63		}
    64		if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:kv_cache_usage_perc"); ok {
    65			sample.CacheUsage = utilization.Float64(cacheUsage)
    66		} else if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "vllm:gpu_cache_usage_perc"); ok {
    67			sample.CacheUsage = utilization.Float64(cacheUsage)
    68		}
    69		return p.cache.Remember(sample)
    70	}
    71	
    72	func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
    73		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
    74		if err != nil {
    75			return "", err
    76		}
    77		resp, err := p.client.Do(req)
    78		if err != nil {
    79			return "", err
    80		}
    81		defer resp.Body.Close()
    82		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
    83			body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
    84			return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
    85		}
    86		body, err := io.ReadAll(resp.Body)
    87		if err != nil {
    88			return "", err
    89		}
    90		return string(body), nil
    91	}

