    15	func TestVLLMUtilizationProbe_CassetteReplay(t *testing.T) {
    16		if testutil.ModeForEnvironment() == recorder.ModeRecordOnly {
    17			t.Skip("cassette replay coverage is exercised in the existing record-mode test")
    18		}
    19	
    20		rec, err := testutil.NewRecorder(testutil.CassettePath("testdata/cassettes", vllmCassetteName))
    21		require.NoError(t, err)
    22		t.Cleanup(func() {
    23			require.NoError(t, rec.Stop())
    24		})
    25	
    26		probe := NewUtilizationProbe("http://replay.invalid/v1", rec.GetDefaultClient())
    27		sample := probe.Probe(context.Background())
    28	
    29		require.Equal(t, utilization.SourceVLLMMetrics, sample.Source)
    30		require.Equal(t, utilization.FreshnessFresh, sample.Freshness)
    31		require.NotNil(t, sample.ActiveRequests)
    32		require.NotNil(t, sample.QueuedRequests)
    33		require.NotNil(t, sample.CacheUsage)
    34		require.Zero(t, *sample.ActiveRequests)
    35		require.Zero(t, *sample.QueuedRequests)
    36		require.NotZero(t, sample.ObservedAt)
    37	}
