    39	func TestVLLMUtilizationProbe_FailureReturnsStaleOrUnknown(t *testing.T) {
    40		var hits int
    41		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    42			require.Equal(t, "/metrics", r.URL.Path)
    43			hits++
    44			if hits == 1 {
    45				_, _ = w.Write([]byte("vllm:num_requests_running 2\nvllm:num_requests_waiting 1\nvllm:kv_cache_usage_perc 0.5\n"))
    46				return
    47			}
    48			http.Error(w, "boom", http.StatusServiceUnavailable)
    49		}))
    50		t.Cleanup(srv.Close)
    51	
    52		probe := NewUtilizationProbe(srv.URL+"/v1", srv.Client())
    53	
    54		fresh := probe.Probe(context.Background())
    55		require.Equal(t, utilization.FreshnessFresh, fresh.Freshness)
    56		require.NotNil(t, fresh.ActiveRequests)
    57		require.Equal(t, 2, *fresh.ActiveRequests)
    58	
    59		stale := probe.Probe(context.Background())
    60		require.Equal(t, utilization.FreshnessStale, stale.Freshness)
    61		require.NotNil(t, stale.ActiveRequests)
    62		require.Equal(t, 2, *stale.ActiveRequests)
    63		require.Equal(t, fresh.ObservedAt, stale.ObservedAt)
    64	}
